{
  "name": "@tetherplane/e2e",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build:deps": "pnpm --filter @tetherplane/compact-mcp build && pnpm --filter @tetherplane/rdc-compat build && pnpm --filter @tetherplane/model-client build && pnpm --filter @tetherplane/browser-bridge build && pnpm --filter @tetherplane/browser-lab build && pnpm --filter @tetherplane/relay build",
    "prebuild": "pnpm run build:deps",
    "build": "tsc -p tsconfig.json",
    "pretest": "cargo build -p tetherd && pnpm run build:deps",
    "test": "node --test --test-concurrency=1 *.test.ts",
    "pretypecheck": "pnpm run build:deps",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "1.30.0",
    "@tetherplane/browser-bridge": "workspace:*",
    "@tetherplane/browser-lab": "workspace:*",
    "@tetherplane/compact-mcp": "workspace:*",
    "@tetherplane/model-client": "workspace:*",
    "@tetherplane/relay": "workspace:*"
  },
  "devDependencies": {
    "@types/node": "24.13.6"
  }
}
